fun ensure_liquidate_borrow_allowed<MarketType, DebtType>(
    liquidation_params: &LiquidationParams,

    obligation: &Obligation<MarketType>,

    emode_group: &EModeGroup,

    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    liquidator_repay_amount: u64,

    x_oracle: &XOracle,

    clock: &Clock,
) {
    // make sure that their obligation still healthy, so users aren't borrowing over their collateral
    let (weighted_debts_value, debts_total_value) = debts_value_usd_for_liquidation(
        emode_group,
        reserves,
        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );

    let (collateral_weighted_value, collateral_total_value) = collaterals_usd_for_liquidation(
        emode_group,
        reserves,
        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );

    // triggering condition: 
    // user_ltv > liquidation_ltv
    if (liquidation_params.liquidation_ltv_threshold_override.is_some()) {
        let liquidation_ltv = *liquidation_params.liquidation_ltv_threshold_override.borrow();
        let user_ltv = weighted_debts_value.div(collateral_total_value);
        assert!(
            user_ltv.gt(liquidation_ltv),
            error::liquidation_obligation_still_safe(),
        );
    } else {
        // user_ltv = weighted_debts_value / collateral_total_value
        // liquidation_ltv = collateral_weighted_value / collateral_total_value
        // user_ltv > liquidation_ltv
        //    weighted_debts_value / collateral_total_value > collateral_weighted_value / collateral_total_value
        //    weighted_debts_value / collateral_weighted_value > liquidation_ltv_threshold
        //    weighted_debts_value > collateral_weighted_value * liquidation_ltv_threshold
        assert!(
            weighted_debts_value.gt(collateral_weighted_value),
            error::liquidation_obligation_still_safe(),
        );
    };

    // Note that the close factor is enforce ONLY when the obligation is not close to bad debt
    let bad_debt_close_factor_bypass_threshold = float::from_quotient(101, 100);
    let bad_debt_threshold = bad_debt_close_factor_bypass_threshold.mul(debts_total_value);

    if (collateral_total_value.le(bad_debt_threshold)) {
        // This means the obligation is close to bad debt, allow close whatever is passed
        // close factor effectively equals to 1.
        return
    };

    let target_debt_type = type_name::with_defining_ids<DebtType>();

    let debt_balance = obligation.debt(target_debt_type).unsafe_debt_amount();
    let debt_value = coin_value(
        get_price(x_oracle, target_debt_type, emode_group.get_oracle_base_token(), clock),
        debt_balance,
        coin_decimals_registry.decimals(target_debt_type)
    )
        // this is tricky, because it is using ceiling, this mean if the debt value is say 9.8, the ceiling is 10
        .ceil();

    // below min usd for close factor enforcement
    if (debt_value <= liquidation_params.close_factor_bypass_min_value) { return };

    let max_debt_amount = debt_balance.mul(liquidation_params.close_factor);
    assert!(
        math::float::from(liquidator_repay_amount).le(max_debt_amount),
        error::liquidation_close_factor_exceeded(),
    );
}

